package com.avsargo.mobile;
import android.app.Activity;
import android.content.Context;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.webkit.WebView;
import android.widget.LinearLayout;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.rule.ActivityTestRule;
import androidx.test.uiautomator.UiDevice;
import org.junit.*;
import org.junit.runner.RunWith;
import org.json.*;
import java.io.*;
import java.lang.reflect.Field;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.Assert.*;
/** Actual bundled ML Kit, Keystore and Android WebViews. Every file/value is synthetic. */
@RunWith(AndroidJUnit4.class)
public final class AdvancedWorkflowTest {
 @Rule public ActivityTestRule<MainActivity> rule=new ActivityTestRule<>(MainActivity.class,false,false);
 private SecureVault vault;private MainActivity activity;
 @Before public void prepare()throws Exception{Context ctx=ApplicationProvider.getApplicationContext();vault=new SecureVault(ctx);vault.eraseAll();vault.saveAiSettings(new JSONObject().put("enabled",true).put("automationConsent",true).put("permissionsVersion",1));vault.saveProfile(new JSONObject().put("fullName","Sample Applicant").put("enterpriseName","Sample Works").put("panNumber","ABCDE1234F").put("dob","21/01/2000").put("gender","Male").put("email","sample@example.com").put("state","Delhi").put("district","Sample District"));activity=rule.launchActivity(null);waitJs("appWeb","!!window.AvsarGoEvent");}
 private WebView web(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return (WebView)f.get(activity);}
 private String js(String view,String expression)throws Exception{AtomicReference<String> result=new AtomicReference<>();CountDownLatch latch=new CountDownLatch(1);WebView w=web(view);InstrumentationRegistry.getInstrumentation().runOnMainSync(()->w.evaluateJavascript(expression,r->{result.set(r);latch.countDown();}));assertTrue("JS callback",latch.await(15,TimeUnit.SECONDS));return result.get();}
 private void waitJs(String view,String condition)throws Exception{long until=System.currentTimeMillis()+30000;while(System.currentTimeMillis()<until){if("true".equals(js(view,condition)))return;Thread.sleep(180);}fail("Timed out: "+condition);}
 private byte[] pdf()throws Exception{PdfDocument doc=new PdfDocument();Paint p=new Paint();p.setColor(Color.BLACK);p.setTextSize(19);String[][] lines={{"Full name: Sample Applicant","Father's name: Sample Parent","Date of birth: 21/01/2000"},{"Address: Sample Lane","City: Delhi","Postal PIN code: 110001"},{"Education board: CBSE","Passing year: 2020","Percentage: 85.50%"},{"Enterprise name: Sample Works","PAN number: ABCDE1234F","Bank name: Sample Bank","IFSC: SBIN0001234"}};for(int i=0;i<lines.length;i++){PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(600,800,i+1).create());page.getCanvas().drawColor(Color.WHITE);int y=110;for(String line:lines[i]){page.getCanvas().drawText(line,40,y,p);y+=55;}doc.finishPage(page);}ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);doc.close();return out.toByteArray();}
 private JSONObject scan(byte[] bytes,String mime)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<JSONObject> result=new AtomicReference<>();AtomicReference<String> error=new AtomicReference<>();new DocumentOcr(activity).recognize(bytes,mime,new DocumentOcr.Listener(){public void result(JSONObject r){result.set(r);latch.countDown();}public void error(String text){error.set(text);latch.countDown();}});assertTrue("Native scan finishes",latch.await(150,TimeUnit.SECONDS));assertNull(error.get());return result.get();}
 @Test public void ocrReadsFourthPdfPageAndCreatesVisionPreviews()throws Exception{JSONObject r=scan(pdf(),"application/pdf");assertEquals(4,r.getInt("pages"));assertEquals(4,r.getInt("totalPages"));assertFalse(r.getBoolean("truncated"));assertTrue(r.getString("text").contains("Sample Works"));assertTrue(r.getString("text").contains("ABCDE1234F"));assertEquals("Sample Works",r.getJSONObject("fields").getString("enterpriseName"));assertEquals(2,r.getJSONArray("images").length());assertTrue(r.getJSONArray("images").getJSONObject(0).getString("data").length()<=260000);File[] files=activity.getCacheDir().listFiles();if(files!=null)for(File f:files)assertFalse("OCR plaintext deleted",f.getName().startsWith("ocr_")&&f.getName().endsWith(".pdf"));screenshot("native-four-page-ocr");}
 @Test public void ocrReadsARealImageAndVaultRoundTripsIt()throws Exception{Bitmap b=Bitmap.createBitmap(1100,850,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);Canvas c=new Canvas(b);Paint p=new Paint();p.setColor(Color.BLACK);p.setTextSize(38);c.drawText("Name: Image Applicant",70,150,p);c.drawText("Email: image@example.com",70,230,p);c.drawText("PAN number: ABCDE1234F",70,310,p);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,90,out);b.recycle();byte[] bytes=out.toByteArray();JSONObject meta=vault.addDocument("Synthetic identity.jpg","image/jpeg",bytes),r=scan(bytes,"image/jpeg");vault.saveScan(meta.getString("id"),r);assertArrayEquals(bytes,vault.documentData(meta.getString("id")));assertTrue(r.getString("text").contains("Image Applicant"));assertEquals("ABCDE1234F",r.getJSONObject("fields").getString("panNumber"));assertEquals(r.getString("text"),new SecureVault(activity).scan(meta.getString("id")).getString("text"));}
 @Test public void permissionsSurviveRecreationAndRevocationStaysRevoked()throws Exception{assertTrue(new SecureVault(activity).automationAllowed());activity.new PrivateBridge().savePermissions(false);long until=System.currentTimeMillis()+5000;while(vault.automationAllowed()&&System.currentTimeMillis()<until)Thread.sleep(100);assertFalse(vault.automationAllowed());vault.saveApplication(new JSONObject().put("analysedIds",new JSONArray().put("old-consented-doc")).put("filledCount",4));assertFalse("Revocation is not inferred back on",new SecureVault(activity).automationAllowed());rule.finishActivity();activity=rule.launchActivity(null);waitJs("appWeb","!!window.AvsarGoEvent");assertFalse(new JSONObject(activity.new PrivateBridge().state()).getJSONObject("ai").getBoolean("automationConsent"));}
 @Test public void previousExplicitV14UseMigratesWithoutAnotherPermissionPopup()throws Exception{vault.saveAiSettings(new JSONObject().put("enabled",true));vault.saveApplication(new JSONObject().put("analysedIds",new JSONArray().put("old-doc")));assertTrue(vault.automationAllowed());assertEquals(1,vault.aiSettings().getInt("permissionsVersion"));}
 @Test public void customerHasNoAdminOrUrlInputAndActualDocumentPickerOpens()throws Exception{assertEquals("false",js("appWeb","/Settings & admin/.test(document.body.innerText)||!!document.getElementById('portalUrl')"));js("appWeb","document.getElementById('attach').click()");UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());long until=System.currentTimeMillis()+10000;while(System.currentTimeMillis()<until&&device.getCurrentPackageName().equals(activity.getPackageName()))Thread.sleep(150);assertFalse("Android picker is a different surface",device.getCurrentPackageName().equals(activity.getPackageName()));device.pressBack();screenshot("native-customer-workspace");}
 @Test public void actualWebViewAutofillsRadioDatesAndUploadsWithoutRepeatingPermission()throws Exception{JSONObject d=vault.addDocument("Synthetic marksheet.pdf","application/pdf",pdf());vault.documentType(d.getString("id"),"marksheet");InstrumentationRegistry.getInstrumentation().runOnMainSync(()->activity.new PrivateBridge().openPortal("https://appassets.androidplatform.net/assets/demo/advanced.html"));waitJs("siteWeb","document.getElementById('applicant')?.value==='Sample Applicant'");assertEquals("\"Sample Works\"",js("siteWeb","document.getElementById('enterprise').value"));assertEquals("\"ABCDE1234F\"",js("siteWeb","document.getElementById('pan').value"));assertEquals("\"21\"",js("siteWeb","document.getElementById('dobDay').value"));assertEquals("\"1\"",js("siteWeb","document.getElementById('dobMonth').value"));assertEquals("true",js("siteWeb","document.getElementById('male').checked"));assertEquals("\"kept@example.com\"",js("siteWeb","document.getElementById('email').value"));assertEquals("\"\"",js("siteWeb","document.getElementById('otp').value"));assertEquals("false",js("siteWeb","document.getElementById('declaration').checked||window.submitted"));assertEquals("undefined",new JSONTokener(js("siteWeb","typeof window.AvsarGoNative")).nextValue());
  waitJs("siteWeb","document.getElementById('certificate').files.length===1");assertEquals("\"Synthetic marksheet.pdf\"",js("siteWeb","document.getElementById('certificate').files[0].name"));js("siteWeb","document.getElementById('next').click()");waitJs("siteWeb","document.getElementById('state').value==='DL'&&document.getElementById('district').value==='Sample District'");screenshot("native-advanced-autofill");}
 private void screenshot(String name)throws Exception{Context ctx=InstrumentationRegistry.getInstrumentation().getTargetContext();File folder=new File(ctx.getExternalFilesDir(null),"verification");folder.mkdirs();UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).takeScreenshot(new File(folder,name+".png"));}
}
